mapper.select:
SELECT *
FROM ROOM_RESERVATION
WHERE RESV_CHECK_IN < #{rangeEnd}
  AND RESV_CHECK_OUT > #{rangeStart}

mapper.update:
UPDATE RESERVATION
SET RESV_STATUS = #{toStatus}
WHERE RESV_STATUS = #{fromStatus}
  AND RESV_NUM IN (
      SELECT RESV_NUM FROM ROOM_RESERVATION
      WHERE ADMIN_IDX = #{adminIdx}
        AND ROOM_IDX = #{roomIdx}
        AND RESV_CHECK_IN <= #{date}
        AND RESV_CHECK_OUT > #{date}
  )

UPDATE ROOM_RESERVATION
SET RESV_STATUS = #{toStatus}
WHERE ADMIN_IDX = #{adminIdx}
  AND ROOM_IDX = #{roomIdx}
  AND RESV_STATUS = #{fromStatus}
  AND RESV_CHECK_IN <= #{date}
  AND RESV_CHECK_OUT > #{date}
